def chunks(xs, n):
    if n <= 0:
        raise ValueError('n must be positive')
    result = []
    current = []
    for item in xs:
        current.append(item)
        if len(current) == n:
            result.append(current)
            current = []
    if current:
        result.append(current)
    return result
